SELECT gen_random_uuid()::text, 'formula', '$a$', 'Apothem of a Regular Polygon', '$a = R\cos\frac{180^\circ}{n} = \frac{s}{2\tan\frac{180^\circ}{n}}$', NULL, 'The apothem is the radius of the inscribed circle of a regular polygon.', '[{"symbol":"$a$","meaning":"apothem, the inradius"},{"symbol":"$R$","meaning":"circumradius"},{"symbol":"$s$","meaning":"side"},{"symbol":"$n$","meaning":"number of sides"}]'::jsonb, '$a$, $R$ and $\frac{s}{2}$ form a right triangle: $R^2 = a^2 + \left(\frac{s}{2}\right)^2$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Plane Geometry' AND t."subject" = 'Mathematics' AND s."normKey" = 'inscribed and circumscribed figures' AND s."active"), 'Squares and polygons', true, 'PENDING', now(), now()
