SELECT gen_random_uuid()::text, 'formula', '$p$', 'Diagonals of a Cyclic Quadrilateral', '$p = \sqrt{\frac{(ac + bd)(ad + bc)}{ab + cd}},\quad q = \sqrt{\frac{(ac + bd)(ab + cd)}{ad + bc}}$', NULL, 'Each diagonal of a cyclic quadrilateral from its four sides.', '[{"symbol":"$a, b, c, d$","meaning":"the sides in order"},{"symbol":"$p$","meaning":"the diagonal that closes the triangle of sides $a$ and $b$"},{"symbol":"$q$","meaning":"the other diagonal"}]'::jsonb, 'Their product is $ac + bd$ (Ptolemy); their ratio is $\frac{p}{q} = \frac{ad + bc}{ab + cd}$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Plane Geometry' AND t."subject" = 'Mathematics' AND s."normKey" = 'ptolemy''s theorem' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Plane Geometry' AND t."subject" = 'Mathematics'
