SELECT gen_random_uuid()::text, 'formula', '$R$', 'Circumradius of a Cyclic Quadrilateral', '$R = \frac14\sqrt{\frac{(ab + cd)(ac + bd)(ad + bc)}{(s-a)(s-b)(s-c)(s-d)}}$', NULL, 'The radius of a cyclic quadrilateral''s circle from its sides (Parameshvara).', '[{"symbol":"$a, b, c, d$","meaning":"the sides"},{"symbol":"$s$","meaning":"semiperimeter"}]'::jsonb, 'The denominator under the root is Brahmagupta''s area squared.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Plane Geometry' AND t."subject" = 'Mathematics' AND s."normKey" = 'ptolemy''s theorem' AND s."active"), NULL, true, 'PENDING', now(), now()
